#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<string> grid(n + 2, string(m + 2, '.'));

    for (int i = 1; i <= n; ++i) {
        string line;
        cin >> line;
        for (int j = 1; j <= m; ++j) {
            grid[i][j] = line[j - 1];
        }
    }

    int output = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (grid[i][j] == 'W') {
                if (grid[i - 1][j] == 'P' ||
                    grid[i + 1][j] == 'P' ||
                    grid[i][j - 1] == 'P' ||
                    grid[i][j + 1] == 'P') {
                    output++;
                }
            }
        }
    }

    cout << output << endl;

    return 0;
}

